			/**
			 * 사이버 상담, 모바일 상담 상담일정 구성
			 * @param {String} psWorkCode 상담 업무코드
			 */
			function setCounsWorkTime(psWorkCode) {
			    
			    var voDsCounsTime = app.lookup("dsCounsWorkTime");
			    var vcGrpCouns = null;
			    
			    // 상담 총 인원 아웃풋 생성
			    setTotalCount(psWorkCode, voDsCounsTime);
			    
			    if (psWorkCode == 1) { // 사이버 상담
			        vcGrpCouns = app.lookup("grpCyberCouns");
			    } else if (psWorkCode == 7) { // 모바일 상담
			        vcGrpCouns = app.lookup("grpMobileCouns");
			    }
			    
			    // filter 적용시 필터된 데이터로 작업한다.
			    voDsCounsTime.setFilter("CONS_PARTY_IDX == '" + psWorkCode + "'");
			    
			    var vnCounsTimeRowCnt = voDsCounsTime.getRowCount();
			    
			    if (vnCounsTimeRowCnt == 0) return false;
			    
			    // 시간인덱스 값으로 중복된 값을 제거하여 시간 컬럼값을 생성한다.
			    // getUnfilteredDistinctValues api 사용시 위에서 적용한 filter 조건이 풀리기때문에 두번째 인자로 filter 식을 적용해줘야한다.
			    var vaDistTimeIdx = voDsCounsTime.getUnfilteredDistinctValues("IDX", function(dataRow) {
			        return dataRow.getValue("CONS_PARTY_IDX") == psWorkCode;
			    });
			    
			    vaDistTimeIdx.forEach(function(timeIdx, idx) {
			        
			        // 프리폼 행추가(기본으로 하나의행이 존재하기 때문에 첫번재 행은 추가하지 않습니다.)
			        if (idx != 0) vcGrpCouns.getLayout().insertRows(["25px"]);
			        
			        var voFindTargetRow = voDsCounsTime.findFirstRow("IDX == '" + timeIdx + "'");
			        var vsStratTime = voFindTargetRow.getValue("START_TIME");
			        var vsEndTime = voFindTargetRow.getValue("END_TIME");
			        var vnKeyIdx = voFindTargetRow.getValue("IDX");
			        
			        // 시간 값에 할당할 아웃풋을 생성합니다.
			        var vcOptTime = new cpr.controls.Output();
			        vcOptTime.value = vsStratTime + " ~ " + vsEndTime;
			        vcOptTime.style.css({
			            "text-align": "center"
			        });
			        
			        // 생성된 시간 아웃풋 컨트롤을 그룹에 넣어줍니다.
			        vcGrpCouns.addChild(vcOptTime, {
			            "colIndex": 0,
			            "rowIndex": idx + 1 // 헤더 로우 +1
			        });
			        
			        // 상담사 업무시간과 매칭시킬 key값을 파라미터로 전달합니다.
			        var vcGrpCounselor = createGrpCounsWorkTime(1, vnKeyIdx);
			        
			        // 생성된 담당자 그룹을 부모 그룹에 넣어줍니다.
			        vcGrpCouns.addChild(vcGrpCounselor, {
			            "colIndex": 1,
			            "rowIndex": idx + 1
			        });
			    });
			}


			/**
			 * 사이버 아웃리치 상담일정 구성
			 */
			function setOutReachWorkTime() {
			        
			    var voDsOutReachTime = app.lookup("dsOutReachTime");
			    var vcGrpCouns = app.lookup("grpOutReachCouns");
			    
			    // 상담 총 인원 아웃풋 생성
			    setTotalCount(null, voDsOutReachTime);
			    
			    var vnRowCnt = voDsOutReachTime.getRowCount();        
			    
			    if (vnRowCnt == 0) return false;
			    
			    // IDX 값으로 중복된 값을 제거하여 시간 컬럼값을 생성한다. 시간별로 IDX 동일   
			    var vaDistTimeIdx = voDsOutReachTime.getUnfilteredDistinctValues("IDX");
			    console.log(vaDistTimeIdx);
			    
			    vaDistTimeIdx.forEach(function(timeIdx, idx) {
			        console.log(timeIdx);
			        console.log(idx);        
			        
			        // 해당 시간 IDX값에 할당된 로우 반환
			        var vaTargetRows = voDsOutReachTime.findAllRow("IDX == '" + timeIdx + "'");
			        console.log(vaTargetRows);
			        
			        // 시작시간은 동일하므로 첫번째 로우에서 시작시간 반환
			        var vaTimeSplit = vaTargetRows[0].getValue("START_TIME").split(":");
			        var vdTime = moment().hour(vaTimeSplit[0]).minute(vaTimeSplit[1]);
			        
			        // 시작시간 기준 +2시간씩 2개의 컬럼을 생성
			        for (var i = 0; i < 2; i++) {
			            // 프리폼 행추가(기본으로 하나의행이 존재하기 때문에 첫번재 행은 추가하지 않습니다.)
			            if (idx != 0 || i != 0) vcGrpCouns.getLayout().insertRows(["25px"]);
			            
			            /* 
			             * moment를 사용하여 add할경우 기존 시간에 2시간이 추가되고 해당 값은 유지되기 때문에
			             * 아래와 같이 적용시 최초 +2, 이후 +2된 시간에서 +2를 적용합니다.
			             */
			            var vsStartTime = vdTime.format("HH:mm");
			            var vsEndTime = vdTime.add(2, "hour").format("HH:mm");
			            
			            // 시간 컬럼에 할당할 아웃풋을 생성합니다.
			            var vcOptTime = new cpr.controls.Output();
			            vcOptTime.value = vsStartTime + " ~ " + vsEndTime;
			            vcOptTime.style.css({
			                "text-align": "center"
			            });
			            
			            // 생성된 시간 아웃풋 컨트롤을 그룹에 넣어줍니다.
			            vcGrpCouns.addChild(vcOptTime, {
			                "colIndex": 0,
			                "rowIndex": (idx * 2) + i + 2 // 헤더 로우 +2
			            });
			            
			            vaTargetRows.forEach(function(row) {
			                
			                var vaWorkType = [];
			                var vsWorkTypeVal = null;
			                var vsWorkType = null;
			                
			                if (i == 0) {
			                    vaWorkType = ["T1_WORK_TYPE", "T3_WORK_TYPE", "T5_WORK_TYPE"];
			                } else {
			                    vaWorkType = ["T2_WORK_TYPE", "T4_WORK_TYPE", "T6_WORK_TYPE"];
			                }
			                
			                // 사이버아웃리치 담당자 근무타입 반환, WORK_TYPE 컬럼 전체를 돌려서 Not Null로 체크
			                for (var j = 0; j < vaWorkType.length; j++) {
			                    var vsTypeVal = row.getValue(vaWorkType[j]);
			                    if (!ValueUtil.isNull(vsTypeVal)) {
			                        vsWorkTypeVal = vsTypeVal;
			                        vsWorkType = vaWorkType[j];
			                        break;
			                    }
			                }
			                
			                var vcGrpCounselor = createGrpCounsWorkTime(2, timeIdx, vsWorkType, vsWorkTypeVal);
			                
			                var vnColIdx = 1;
			                switch (vsWorkTypeVal) {
			                    case "f" : vnColIdx = 1; //facebook      
			                        break;
			                    case "i" : vnColIdx = 2; //instagram           
			                        break;
			                    case "t" : vnColIdx = 3; //트위터              
			                        break;
			                    case "c" : vnColIdx = 4; //채팅                 
			                        break;
			                    default:
			                        break;
			                }
			                
			                // 생성된 담당자 그룹을 부모 그룹에 넣어줍니다.
			                vcGrpCouns.addChild(vcGrpCounselor, {
			                    "colIndex": vnColIdx,
			                    "rowIndex": (idx * 2) + i + 2
			                });
			                
			            });
			            
			        }
			    });
			}

			/**
			 * 상담 총 인원 출력 아웃풋 생성
			 * @param {Number} psWorkCode? 상담업무 구분 코드
			 * @param {cpr.data.DataSet} poDataSet? 조회할 데이터 셋
			 */
			function setTotalCount(psWorkCode, poDataSet) {
			    var voDsCounsTime = poDataSet;
			    var voDsCounsTime, vcOptTotal;
			    
			    if (psWorkCode == 1 || psWorkCode == 7) { // 사이버 상담, 모바일 상담
			        // 업무 구분코드에 따라 필터된 데이터로 작업한다.
			        voDsCounsTime.setFilter("CONS_PARTY_IDX == '" + psWorkCode + "'");
			        if(psWorkCode == 1){
			            vcOptTotal = app.lookup("optCyberTotal");
			        } else {
			            vcOptTotal = app.lookup("optMobileTotal");
			        } 
			        
			    } else { // 사이버 아웃리치      
			        vcOptTotal = app.lookup("optOutReachTotal");
			    }
			        
			    var vnTotalCount = voDsCounsTime.getRowCount();
			    var vnHoliCount = voDsCounsTime.findAllRow("HOLI_STATUS == '승인'").length;
			    var vnWorkCount = vnTotalCount - vnHoliCount;
			    
			    vcOptTotal.value = "· 전체  :  " + vnTotalCount + "명   · 근무  :  " + vnWorkCount + "명   · 휴가  :  " + vnHoliCount + "명";
			}

			/**
			 * 담당자 그룹을 생성합니다.
			 * @param {Number} psSetType 상담분류 코드 1 : 사이버상담,모바일 상담, 2: 사이버 아웃리치
			 * @param {String} psConsIdx 상담시간에 대한 key 값
			 * @param {String} psWorkTypeColNm? 사이버 아웃리치 상담업무 컬럼명
			 * @param {String} psWorkTypeVal? 사이버 아웃리치 상담업무 컬럼값
			 * @return {cpr.controls.Container} 상담자명 그룹
			 */
			function createGrpCounsWorkTime(psSetType, psConsIdx, psWorkTypeColNm, psWorkTypeVal) {
			    
			    var voDsCounsTime;
			    var vaFindRows;
			    
			    if (psSetType == 1) { // 사이버 상담, 모바일 상담
			        voDsCounsTime = app.lookup("dsCounsWorkTime");
			        
			        // 상담시간 key값(IDX)과 매칭되는 로우를 찾습니다.
			        vaFindRows = voDsCounsTime.findAllRow("IDX == '" + psConsIdx + "'");        
			    } else if (psSetType == 2) { // 사이버 아웃리치
			        voDsCounsTime = app.lookup("dsOutReachTime");
			        
			        // 상담시간 key값(IDX)과  업무구분으로 매칭되는 로우를 찾습니다.
			        vaFindRows = voDsCounsTime.findAllRow("IDX == '" + psConsIdx + "' &&" + psWorkTypeColNm + "=='" + psWorkTypeVal + "'");
			    }
			    
			    if (vaFindRows.length == 0) return false;
			    
			    // 상담사명을 담을 flow 레이아웃 그룹 생성
			    var vcGrpFlow = new cpr.controls.Container("");
			    var voFlowLayout = new cpr.controls.layouts.FlowLayout();
			    voFlowLayout.scrollable = false;
			    voFlowLayout.horizontalSpacing = 0;
			    vcGrpFlow.setLayout(voFlowLayout);
			    (function(container) {
			        
			        vaFindRows.forEach(function(row) { // row 객체로 반복문
			            var vsInsDate = row.getValue("INS_DATE"); // 기준날짜
			            var vsCounsNm = row.getValue("CONS_NAME");
			            var vsHoliStatus = row.getValue("HOLI_STATUS");
			            
			            if (vsHoliStatus == "승인") { // 휴가자일경우            
			                var vcGrpHoli = new cpr.controls.Container("grpHoli");
			                var voFormLayout = new cpr.controls.layouts.FormLayout();
			                voFormLayout.scrollable = false;
			                voFormLayout.horizontalSpacing = "0px";
			                voFormLayout.verticalSpacing = "0px";
			                voFormLayout.setColumns(["40px", "20px", "10px"]);
			                voFormLayout.setColumnAutoSizing(0, true);
			                voFormLayout.setColumnAutoSizing(1, true);
			                voFormLayout.setColumnAutoSizing(2, true);
			                voFormLayout.setRows(["1fr"]);
			                vcGrpHoli.setLayout(voFormLayout);
			                (function(subContainer) {
			                    var optNm = new cpr.controls.Output("optNm");
			                    optNm.value = vsCounsNm + "(";
			                    optNm.style.css({
			                        "padding-right": "0px",
			                        "text-align": "right"
			                    });
			                    subContainer.addChild(optNm, {
			                        "colIndex": 0,
			                        "rowIndex": 0
			                    });
			                    var optHoliType = new cpr.controls.Output("optHoliType");
			                    optHoliType.value = "휴가";
			                    optHoliType.style.css({
			                        "color": "#ff0000",
			                        "padding-left": "0px",
			                        "padding-right": "0px"
			                    });
			                    subContainer.addChild(optHoliType, {
			                        "colIndex": 1,
			                        "rowIndex": 0
			                    });
			                    var optSub = new cpr.controls.Output("optSub");
			                    optSub.value = ")";
			                    optSub.style.css({
			                        "padding-left": "0px"
			                    });
			                    subContainer.addChild(optSub, {
			                        "colIndex": 2,
			                        "rowIndex": 0
			                    });
			                })(vcGrpHoli);
			                container.addChild(vcGrpHoli, {
			                    "autoSize": "width",
			                    "width": "40px",
			                    "height": "25px"
			                });
			                
			            } else { // 근무자일경우
			                var vcOptCouns = new cpr.controls.Output("");
			                vcOptCouns.value = vsCounsNm;
			                container.addChild(vcOptCouns, {
			                    "autoSize": "width",
			                    "width": "40px",
			                    "height": "25px"
			                });
			            }
			        });
			        
			    })(vcGrpFlow);
			    
			    return vcGrpFlow;
			}

